from .partial_json import parse_partial_json

log = logging.getLogger(__name__)

# 'streaming' | 'running' | 'done' | 'error' | 'denied' | 'interrupted' | 'background'
ToolStatus = str

RawMsg = Dict[str, Any]
ContentBlock = Dict[str, Any]
ToolInput = Dict[str, Any]
StructuredResult = Dict[str, Any]


@dataclass
class UserCommand:
    name: str
    args: str


@dataclass(eq=False)
class UserItem:
    kind: ClassVar[str] = "user"
    id: str
    uuid: str
    text: str
    images: List[str] = field(default_factory=list)
    files: List[str] = field(default_factory=list)
    local: bool = False
    command: Optional[UserCommand] = None
    prev_uuid: Optional[str] = None
    rev: int = 0
    ts: Optional[float] = None
    # The subagent tool this item sits under, or None at the top level (set by the model, read by bump).
    _parent: Optional[str] = None


@dataclass(eq=False)
class TextItem:
    kind: ClassVar[str] = "text"
    id: str
    text: str
    streaming: bool
    rev: int = 0
    ts: Optional[float] = None
    _parent: Optional[str] = None


@dataclass(eq=False)
class ThinkingItem:
    kind: ClassVar[str] = "thinking"
    id: str
    text: str
    streaming: bool
    start_ts: float
    end_ts: Optional[float] = None
    redacted: bool = False
    rev: int = 0
    ts: Optional[float] = None
    _parent: Optional[str] = None


@dataclass
class ToolResult:
    text: str
    images: List[str] = field(default_factory=list)
    is_error: bool = False


@dataclass
class TaskInfoPatch:
    """What a task_started / task_progress / task_notification message says about a background task."""

    task_id: str
    status: Optional[str] = None
    summary: Optional[str] = None
    output_file: Optional[str] = None
    usage: Any = None


@dataclass(eq=False)
class ToolItem:
    kind: ClassVar[str] = "tool"
    id: str
    name: str
    input: ToolInput = field(default_factory=dict)
    input_json: str = ""
    input_done: bool = False
    status: ToolStatus = "running"
    result: Optional[ToolResult] = None
    structured: Optional[StructuredResult] = None
    children: List[Item] = field(default_factory=list)
    start_ts: float = 0
    end_ts: Optional[float] = None
    elapsed: Optional[float] = None
    parent_id: Optional[str] = None
    task_id: Optional[str] = None
    task: Optional[TaskInfoPatch] = None  # status is always set once a task is attached
    summary: Optional[str] = None
    rev: int = 0
    ts: Optional[float] = None
    _parent: Optional[str] = None


@dataclass(eq=False)
class NoticeItem:
    kind: ClassVar[str] = "notice"
    id: str
    level: str  # 'info' | 'warning' | 'error' | 'success'
    text: str
    detail: Optional[str] = None
    tag: Optional[str] = None
    count: Optional[int] = None
    rev: int = 0
    ts: Optional[float] = None
    _parent: Optional[str] = None


@dataclass(eq=False)
class ResultItem:
    kind: ClassVar[str] = "result"
    id: str
    ok: bool
    subtype: str
    duration_ms: float
    cost_usd: float
    turns: int
    input_tokens: Optional[int] = None
    output_tokens: Optional[int] = None
    text: Optional[str] = None
    errors: Optional[List[str]] = None
    chain_uuid: Optional[str] = None
    rev: int = 0
    ts: Optional[float] = None
