        self.search_ico.setPixmap(icons.pixmap("search", t.text_3, 16))
        tl.addWidget(self.search_ico)
        self.input = QLineEdit()
        self.input.setProperty("quiet", "true")
        self.input.setProperty("autofocus", True)
