    def _focus_first(self) -> None:
        if self._closing:
            return
        for cls in (QLineEdit, QPlainTextEdit, QComboBox):
            for w in self.frame.findChildren(cls):
                if w.isVisible() and w.isEnabled() and w.focusPolicy() != Qt.FocusPolicy.NoFocus:
