def open_sheet(key: str) -> Optional[Sheet]:
    """The sheet open for a store key, if any."""
    s = _open.get(key)
    return s if s is not None and not s._closing else None


def close_sheet(key: str) -> None:
    s = open_sheet(key)
    if s is not None:
        s.dismiss(reset=False)
