        # main column
        self.main = QWidget()
        self.main_lay = QVBoxLayout(self.main)
        self.main_lay.setContentsMargins(0, 0, 0, 0)
        self.main_lay.setSpacing(24)
        self.main_lay.setAlignment(Qt.AlignmentFlag.AlignTop)
