        self.ico_box.setStyleSheet(f"#tile-ico {{ background: {box_bg}; border-radius: 10px; }}")
        self.ico.setPixmap(
            icons.pixmap(self._icon, t.accent_text if accent else (t.text if self._live else t.text_2), 16)
        )
        self.ico.setVisible(not self._live)
