        bl.setSpacing(28)
        hh.addWidget(self.body)
        hh.addStretch(1)
        self.scroll.setWidget(host)
        self.scroll.viewport().installEventFilter(self)
        root.addWidget(self.scroll, 1)

        # the four tiles
        stats = QWidget()
        sl = QHBoxLayout(stats)
