        )
        self.gauge_line.setTextFormat(Qt.TextFormat.RichText)
        sl.addWidget(self.gauge_line)
        stats = QHBoxLayout()
        stats.setSpacing(18)
        for k, v in (
            ("Cost so far", cost(float(usage.get("costUsd") or 0))),
            ("Output tokens", tokens(int(usage.get("outputTokens") or 0))),
        ):
            box = QVBoxLayout()
            box.setSpacing(2)
