        il.addWidget(_mono(f"{self.sid[:13]}…", shrink=False))
        cp = IconButton("copy", "Copy session ID", 12)
        cp.clicked.connect(lambda: (copy_text(self.sid), store.toast("Copied", "success")))
        il.addWidget(cp)
        il.addStretch(1)
        s.add(
