        lay.addWidget(self.ico)
        self.lb = QLabel()
        lay.addWidget(self.lb)
        self.chev = QLabel()
        lay.addWidget(self.chev)
        bind(theme.theme.changed, self, lambda _t: self._paint())
        self._paint()

    def set_text(self, text: str) -> None:
        self._text = text
