  const { id: sessionId } = await sessions.create({ cwd: s.cwd, worktree: s.worktree ? { name: s.name } : null, mode: s.mode === 'deny' ? 'default' : s.mode, model: s.model || undefined, effort: s.effort || undefined, title: `${s.name} · ${stamp}` });
