export const useStore = create<State>(() => ({
  connected: false,
  everConnected: false,
  info: null,
  config: null,
  sessions: [],
  sessionsLoaded: false,
  activeId: null,
  rt: {},
  ui: { sidebar: true, panel: false, panelTab: 'changes', sidebarW: 268, panelW: 560, showArchived: false, diffMode: 'unified', view: 'normal' },
  dialogs: { newSession: null, settings: false, palette: false, shortcuts: false, confirm: null, mcpAuth: null },
  toasts: [],
  fsRev: 0,
  unread: {},
  fileOpen: null,
  composerInsert: null,
  theme: 'dark',
  gatewayModels: null,
  timeline: {},
  page: 'session',
  inboxUnread: 0,
  schedRev: 0,
  scheduleDialog: null,
  lightbox: null,
