/* ================================================================ shell */

.app {
  display: flex;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
  background: var(--chrome);
}

/* ---- the opening. Matches the inline splash in index.html frame for frame, then takes over:
   the bowl lands, the bar and stems set down, the name settles; the bowl breathes while we wait. */
.boot {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 18px;
  color: var(--text-3);
  background: var(--canvas);
  animation: boot-in var(--t-med) var(--ease);
}
.boot.leaving {
  animation: boot-out 320ms var(--ease-exit) forwards;
  pointer-events: none;
}
@keyframes boot-in {
  from {
    opacity: 0.999;
  }
}
@keyframes boot-out {
  to {
    opacity: 0;
    transform: scale(1.02);
  }
}
.boot-stage {
  display: grid;
  justify-items: center;
  gap: 12px;
}
.boot-mark {
  overflow: visible;
  color: var(--text-2);
}
.boot-bowl {
  fill: var(--accent);
  transform-origin: 10.6px 9.2px;
  animation: boot-bowl 640ms var(--spring) both, boot-breathe 2.4s var(--ease-io) 900ms infinite;
}
.boot-bar,
.boot-stem {
  fill: currentColor;
  transform-origin: 12.4px 5.1px;
  animation: boot-set 520ms var(--ease) both;
}
.boot-bar {
  transform-origin: 10.6px 6px;
  animation-name: boot-bar;
  animation-delay: 160ms;
}
.boot-stem.s1 {
  animation-delay: 240ms;
}
.boot-stem.s2 {
  transform-origin: 15.3px 5.1px;
  animation-delay: 320ms;
}
.boot.linked .boot-bowl {
  animation: boot-bowl 640ms var(--spring) both, boot-settle 400ms var(--ease) forwards;
}
@keyframes boot-bowl {
  from {
    transform: scale(0.4);
    opacity: 0;
  }
}
@keyframes boot-bar {
  from {
    transform: scaleX(0);
    opacity: 0;
  }
}
@keyframes boot-set {
  from {
    transform: scaleY(0);
    opacity: 0;
  }
}
@keyframes boot-breathe {
  50% {
    transform: scale(0.86);
    opacity: 0.7;
  }
}
@keyframes boot-settle {
  to {
    transform: scale(1);
    opacity: 1;
  }
}
.boot-name {
  font-size: var(--fs-title);
  font-weight: 600;
  letter-spacing: -0.012em;
  color: var(--text);
  animation: boot-name 600ms var(--ease) 420ms both;
}
@keyframes boot-name {
  from {
    opacity: 0;
    transform: translateY(4px);
    letter-spacing: 0.04em;
  }
}
.boot-line {
  min-height: 18px;
  max-width: 340px;
  text-align: center;
  font-size: var(--fs-small);
  line-height: 1.5;
  color: var(--text-4);
  animation: fade var(--t-slow) var(--ease) 700ms both;
}
.boot-line.long {
  color: var(--text-3);
}
@keyframes breathe {
  50% {
    opacity: 0.4;
  }
}
.quit-note {
  height: 100vh;
  display: grid;
  place-content: center;
  color: var(--text-2);
  font: 14px var(--font-ui);
}

.main {
  flex: 1;
  min-width: 340px;
  /* The reading column is the golden section of the pane (about 62%), so the two margins together
     make up the remaining 38% whatever the window size; it never drops under 640px (margins give
     way first, down to 24px) and stops growing at 1080px, where the margins start to take all the
     extra room. This is the proportion Claude's own desktop app settles on. */
  --col: clamp(640px, min(61.8%, 100% - 48px), 1080px);
  display: flex;
  flex-direction: column;
  position: relative;
  background: var(--canvas);
}

.offline {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 7px 14px;
  font-size: var(--fs-small);
  color: var(--text-2);
  background: var(--fill-1);
  box-shadow: inset 0 -1px 0 var(--hair);
  animation: fade var(--t-med) var(--ease);
}

/* Drag handles: invisible until hovered, then a hairline that thickens. */
.resizer {
  width: 9px;
  margin: 0 -4px;
  cursor: col-resize;
  position: relative;
  z-index: 5;
  flex: none;
}
/* No standing line: the two surfaces meet by tone alone. A short handle appears under the pointer. */
.resizer::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 3px;
  width: 3px;
  height: 40px;
  margin-top: -20px;
  border-radius: 2px;
  background: var(--hair-3);
  opacity: 0;
  transform: scaleY(0.6);
  transition: opacity var(--t-med) var(--ease), transform var(--t-med) var(--ease), background var(--t-fast);
}
.resizer:hover::after {
  opacity: 1;
  transform: none;
  transition-delay: 120ms;
}
.resizer.active::after {
  opacity: 1;
  transform: none;
  background: var(--accent);
}
body.resizing {
  cursor: col-resize;
  user-select: none;
}
body.resizing iframe {
  pointer-events: none;
}

/* ================================================================ sidebar */

.sidebar {
  flex: 0 1 auto; /* in a small window the sidebar gives up width too, down to its minimum */
  display: flex;
  flex-direction: column;
  background: var(--chrome);
  min-width: 210px;
}

.side-top {
  padding: 12px 10px 6px;
  display: grid;
  grid-template-columns: minmax(0, 1fr); /* the search field may not push its clear button past the edge */
  gap: 2px;
}

/* the mark takes the same 15px slot as the row icons under it, so the name lines up with their labels */
.brand {
  display: flex;
  align-items: center;
  gap: 9px;
  height: 30px;
  padding: 0 8px 6px;
  color: var(--text);
}
.brand .mark {
  flex: none;
  width: 15px;
}
.brand-name {
  font-weight: 600;
  font-size: 13.5px;
  letter-spacing: -0.01em;
}

.side-new,
.side-search {
  display: flex;
  align-items: center;
  gap: 9px;
  height: 30px;
  padding: 0 8px;
  border-radius: var(--r-2);
  color: var(--text-2);
  font-size: var(--fs-ui);
  text-align: left;
  transition: background var(--t-fast), color var(--t-fast);
}
.side-new:hover {
  background: var(--fill-2);
  color: var(--text);
}
.side-new:active {
