}
.side-row-main {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  padding: 5px 4px 5px 8px;
  text-align: left;
}
.side-row-text {
  min-width: 0;
  flex: 1;
  display: grid;
  gap: 1px;
}
.side-row-title {
  min-width: 0;
  font-size: var(--fs-ui);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--text-2);
  transition: color var(--t-fast);
}
.side-row:hover .side-row-title,
.side-row.active .side-row-title {
  color: var(--text);
}
.side-row.unread .side-row-title {
  color: var(--text);
  font-weight: 560;
}
.side-row-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--fs-micro);
  color: var(--text-3);
