  align-items: center;
  gap: 2px;
  padding: 8px 10px 10px;
}
.side-foot-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 28px;
  padding: 0 8px;
  border-radius: var(--r-2);
  color: var(--text-3);
  font-size: var(--fs-ui);
  transition: background var(--t-fast), color var(--t-fast);
}
.side-foot-btn:hover {
  background: var(--fill-2);
  color: var(--text);
}

/* status marks: running = rotating arc, needs = amber dot with a halo, unread = small neutral dot */
.glyph {
  flex: none;
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  position: relative;
}
.glyph.unread {
  width: 6px;
  height: 6px;
  background: var(--text-2);
}
.glyph.error {
  background: var(--err);
}
.glyph.needs {
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-wash);
  animation: halo 2.4s var(--ease-io) 3;
}
@keyframes halo {
  50% {
    box-shadow: 0 0 0 5px transparent;
  }
}
.glyph.running {
  width: 11px;
  height: 11px;
  border: 1.5px solid var(--fill-3);
  border-top-color: var(--text-2);
  animation: spin 0.9s linear infinite;
}

/* ================================================================ session */

.session {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  animation: fade var(--t-med) var(--ease);
}

.session-head {
  position: relative;
  container-type: inline-size;
  z-index: 2;
  flex: none;
  display: flex;
  align-items: center;
  gap: 12px;
  height: var(--header-h);
  padding: 0 10px 0 20px;
  background: var(--canvas);
  transition: box-shadow var(--t-med);
}
.session-head.scrolled {
  box-shadow: 0 1px 0 var(--hair);
}
.session-title-wrap {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}
.session-title {
  margin: 0;
  min-width: 0;
  flex: 0 1 auto;
  font-size: 13.5px;
  font-weight: 600;
  letter-spacing: -0.006em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: default;
}
.title-input {
  height: 28px;
  max-width: 420px;
  font-weight: 600;
}
.session-crumbs {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 0 10 auto;
  color: var(--text-3);
  font-size: var(--fs-small);
  white-space: nowrap;
  overflow: hidden;
}
.crumb {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.crumb svg {
  opacity: 0.8;
}
.crumb.wt {
  color: var(--plan);
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  flex: none;
  height: 22px;
  padding: 0 4px;
  font-size: var(--fs-small);
  font-weight: 500;
  color: var(--text-3);
  animation: fade var(--t-med) var(--ease);
}
.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.status-pill.running .status-dot,
.status-pill.starting .status-dot {
  animation: breathe 1.2s ease-in-out infinite;
}
.status-pill.requires_action {
  color: var(--accent-text);
  font-weight: 550;
}
.status-pill.error {
  color: var(--err);
}

.session-actions {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: none;
}
.diffstat {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0 9px;
  margin-right: 4px;
  border-radius: 13px;
  background: var(--fill-1);
  box-shadow: inset 0 0 0 1px var(--hair);
  transition: background var(--t-fast), box-shadow var(--t-fast);
  animation: pop var(--t-med) var(--ease);
}
.diffstat:hover,
.diffstat.on {
