  font-weight: 560;
  letter-spacing: -0.02em;
}
.session-empty-git {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--fs-small);
}
.examples {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  max-width: 560px;
  margin-top: 22px;
}
.example {
  height: 32px;
  padding: 0 14px;
  border-radius: 16px;
  font-size: var(--fs-ui);
  color: var(--text-2);
  background: var(--fill-1);
  box-shadow: inset 0 0 0 1px var(--hair);
  transition: background var(--t-fast), color var(--t-fast), transform var(--t-fast) var(--ease);
}
.example:hover {
  background: var(--fill-2);
  color: var(--text);
}
.example:active {
